ControlPropertyState.AutoRuleBindingString:
// =========================
// btnCT_Load.OnSelect
// =========================

// 0) Guard: no record
If(
    IsBlank(varDrawerRecordId) || varDrawerRecordId = 0,
    Set(varCT_Error, "No record selected.");
    Set(varCT_IsLoading, false);
    false,

    // 1) LoadKey (evita recargas)
    Set(varCT_NewLoadKey, Text(varDrawerProjectId) & "|" & Text(varDrawerEntityType) & "|" & Text(varDrawerRecordId));

    If(
        varCT_LoadKey = varCT_NewLoadKey && !IsEmpty(colCT_Merged),
        true,

        Set(varCT_LoadKey, varCT_NewLoadKey);

        Set(varCT_IsLoading, true);
        Set(varCT_Error, "");
        Set(varCT_IsDirty, false);

        // Limpia dirty
        Clear(colCT_Dirty);

        // 2) Flow (UNA sola llamada)
        Set(
            varCT_Resp,
            WarRoom_GetCustomBundle.Run(
                varDrawerProjectId,
                varDrawerEntityType,
                varDrawerRecordId
        );

        // 3) Extraer result (texto)
        Set(varCT_ResultText, Coalesce(Text(varCT_Resp), ""));

        If(
            varCT_ResultText = "",
            Set(varCT_Error, "Flow returned empty result.");
            Clear(colCT_Merged);
            Clear(colCT_Quick);
            Set(varCT_IsLoading, false);
            false,

            // 4) Parse + normalizar tabla tipada
            Set(varCT_Bundle, ParseJSON(varCT_ResultText));

            ClearCollect(
                colCT_Merged,
                ForAll(
                    Table(varCT_Bundle.merged) As r,
                    {
                        FieldKey: Text(r.Value.FieldKey),
                        Label: Text(r.Value.Label),
                        FieldType: Text(r.Value.FieldType),
                        HelpText: Text(r.Value.HelpText),

                        IsRequired: Coalesce(Boolean(r.Value.IsRequired), false),
                        IsPinned: Coalesce(Boolean(r.Value.IsPinned), false),
                        SortOrder: Coalesce(Value(Text(r.Value.SortOrder)), 0),
                        OptionsJson: Text(r.Value.OptionsJson),

                        ValueText: Text(r.Value.ValueText),
                        ValueNumber: If(IsBlank(Text(r.Value.ValueNumber)), Blank(), Value(Text(r.Value.ValueNumber))),
                        ValueDate: If(IsBlank(Text(r.Value.ValueDate)), Blank(), DateValue(Text(r.Value.ValueDate))),
                        ValueBool: Coalesce(Boolean(r.Value.ValueBool), false),
                        ValueJson: Text(r.Value.ValueJson),

                        LastUpdatedOn: If(IsBlank(Text(r.Value.LastUpdatedOn)), Blank(), DateTimeValue(Text(r.Value.LastUpdatedOn))),
                        LastUpdatedByEmail: Text(r.Value.LastUpdatedByEmail)
                    }
                )
            );

            // 5) Quick (pinned)
            ClearCollect(colCT_Quick, Filter(colCT_Merged, IsPinned));

            Set(varCT_IsLoading, false);
            true
        
            ) 
        )
    )
);

Set(varIsLoadingComments, true);

Set(
    varAddResp,
    Warroom_AddTaskComment.Run(
        cmp_DetailDrawer.ProjectId,
        cmp_DetailDrawer.RecordId,
        txtNewComment.Value,
        User().Email,
        cmp_DetailDrawer.EntityType,
        User().FullName,
        ddCommentType.Selected.Value

    )
);

Reset(txtNewComment);
Reset(ddCommentType);

// Recarga page 1
Set(varCommentsPage, 1);

Set(
    varCommResp,
    Warroom_GetTaskCommentsPaged.Run(
        cmp_DetailDrawer.ProjectId,
        cmp_DetailDrawer.RecordId,
        varCommentsPage,
        varCommentsPageSize,
        cmp_DetailDrawer.EntityType
    )
);

ClearCollect(
    colComments,
    ForAll(
        Table(ParseJSON(varCommResp.result)),
        {
            CommentId: Value(ThisRecord.Value.CommentId),
            TaskId: Value(ThisRecord.Value.TaskId),
            CommentType: Text(ThisRecord.Value.CommentType),
            CreatedOn: DateTimeValue(Text(ThisRecord.Value.CreatedOn)),
            CreatedByEmail: Text(ThisRecord.Value.CreatedByEmail),
            CreatedByName: Text(ThisRecord.Value.CreatedByName),
            ModifiedOn: DateTimeValue(Text(ThisRecord.Value.ModifiedOn)),
            ModifiedByEmail: Text(ThisRecord.Value.ModifiedByEmail),
            CommentText: Text(ThisRecord.Value.CommentText),
            TotalRows: Value(ThisRecord.Value.TotalRows),
            TotalPages: Value(ThisRecord.Value.TotalPages),
            PageNumber: Value(ThisRecord.Value.PageNumber),
            PageSize: Value(ThisRecord.Value.PageSize)
        }
    )
);

Set(varCommentsTotalRows,  Coalesce(First(colComments).TotalRows, 0));
Set(varCommentsTotalPages, Coalesce(First(colComments).TotalPages, 0));

Set(varIsLoadingComments, false);

RemoveIf(colCT_Dirty, FieldKey = ThisItem.FieldKey);

Collect(
    colCT_Dirty,
    {
        FieldKey: ThisItem.FieldKey,
        FieldType: ThisItem.FieldType,
        ValueText: "",
        ValueNumber: Blank(),
        ValueDate: Self.SelectedDate,
        ValueBool: false,
        ValueJson: ""
    }
);

Patch(
    colCT_Quick,
    LookUp(colCT_Quick, FieldKey = ThisItem.FieldKey),
    { ValueDate: Self.SelectedDate }
);

Set(varCT_IsDirty, true)

Set(varDrawerTab, Coalesce(tabDetail.Selected.Value, "Overview"));

If(
    IsBlank(cmp_DetailDrawer.RecordId) || Value(cmp_DetailDrawer.RecordId) = 0,
    Notify("No record selected.", NotificationType.Warning
) ,

    Switch(
        varDrawerTab,

        // =========================
        // COMMENTS TAB
        // =========================
        "Comments",

            Set(varIsLoadingComments, true);
            Set(varCommentsPageSize, Coalesce(varCommentsPageSize, 20));
            Set(varCommentsPage, 1);

            // Asegura schema tipado de colComments (1 vez)
            If(
                IsEmpty(colComments),
                ClearCollect(
                    colComments,
                    Table(
                        {
                            CommentId: 0,
                            TaskId: 0,
                            CommentText: "",
                            CommentType: "",
                            CreatedOn: Now(),
                            CreatedByEmail: "",
                            CreatedByName: "",
                            ModifiedOn: Now(),
                            ModifiedByEmail: "",
                            TotalRows: 0,
                            TotalPages: 0,
                            PageNumber: 1,
                            PageSize: 20
                        }
                    )
                );
                Clear(colComments)
            );

            Set(
                varCommResp,
                Warroom_GetTaskCommentsPaged.Run(
                    cmp_DetailDrawer.ProjectId,
                    cmp_DetailDrawer.RecordId,
                    varCommentsPage,
                    varCommentsPageSize,
                    cmp_DetailDrawer.EntityType
                )
            );

            Set(varCommResultText, Coalesce(Text(varCommResp.result), ""));

            If(
                varCommResultText = "",
                Clear(colComments);
                Set(varCommentsTotalRows, 0);
                Set(varCommentsTotalPages, 0),
                
                ClearCollect(
                    colComments,
                    ForAll(
                        Table(ParseJSON(varCommResultText)),
                        {
                            CommentId: Value(ThisRecord.Value.CommentId),
                            TaskId: Value(ThisRecord.Value.TaskId),
                            CommentType: Text(ThisRecord.Value.CommentType),
                            CreatedOn: DateTimeValue(Text(ThisRecord.Value.CreatedOn)),
                            CreatedByEmail: Text(ThisRecord.Value.CreatedByEmail),
                            CreatedByName: Text(ThisRecord.Value.CreatedByName),
                            ModifiedOn: DateTimeValue(Text(ThisRecord.Value.ModifiedOn)),
                            ModifiedByEmail: Text(ThisRecord.Value.ModifiedByEmail),
                            CommentText: Text(ThisRecord.Value.CommentText),
                            TotalRows: Value(ThisRecord.Value.TotalRows),
                            TotalPages: Value(ThisRecord.Value.TotalPages),
                            PageNumber: Value(ThisRecord.Value.PageNumber),
                            PageSize: Value(ThisRecord.Value.PageSize)
                        }
                    )
                );

                Set(varCommentsTotalRows,  Coalesce(First(colComments).TotalRows, 0));
                Set(varCommentsTotalPages, Coalesce(First(colComments).TotalPages, 0))
            );

            Set(varIsLoadingComments, false),

        // =========================
        // CUSTOM TAB
        // =========================
        "Custom",
        If(
            IsBlank(cmp_DetailDrawer.RecordId) || cmp_DetailDrawer.RecordId = 0,
            Notify("No record selected.", NotificationType.Warning)
        ),

        // =========================
        // DEFAULT: no action
        // =========================
        true
    )
);

RemoveIf(colCT_Dirty, FieldKey = ThisItem.FieldKey);

Collect(
    colCT_Dirty,
    {
        FieldKey: ThisItem.FieldKey,
        FieldType: ThisItem.FieldType,
        ValueText: "",
        ValueNumber: Blank(),
        ValueDate: Blank(),
        ValueBool: true,
        ValueJson: ""
    }
);

Patch(
    colCT_Merged_UI,
    LookUp(colCT_Merged_UI, FieldKey = ThisItem.FieldKey),
    {
        ValueBool: true
    }
);

Patch(
    colCT_Quick,
    LookUp(colCT_Quick, FieldKey = ThisItem.FieldKey),
    {
        ValueBool: true
    }
);

Set(varCT_IsDirty, true);

RemoveIf(colCT_Dirty, FieldKey = ThisItem.FieldKey);

Collect(
    colCT_Dirty,
    {
        FieldKey: ThisItem.FieldKey,
        FieldType: ThisItem.FieldType,
        ValueText: "",
        ValueNumber: Blank(),
        ValueDate: Blank(),
        ValueBool: false,
        ValueJson: ""
    }
);

Patch(
    colCT_Merged_UI,
    LookUp(colCT_Merged_UI, FieldKey = ThisItem.FieldKey),
    {
        ValueBool: false
    }
);

Patch(
    colCT_Quick,
    LookUp(colCT_Quick, FieldKey = ThisItem.FieldKey),
    {
        ValueBool: false
    }
);

Set(varCT_IsDirty, true);

RemoveIf(colCT_Dirty, FieldKey = ThisItem.FieldKey);

Collect(
    colCT_Dirty,
    {
        FieldKey: ThisItem.FieldKey,
        FieldType: ThisItem.FieldType,
        ValueText: Self.Text,
        ValueNumber: Blank(),
        ValueDate: Blank(),
        ValueBool: false,
        ValueJson: ""
    }
);

Patch(
    colCT_Merged_UI,
    LookUp(colCT_Merged_UI, FieldKey = ThisItem.FieldKey),
    {
        ValueText: Self.Text
    }
);

Patch(
    colCT_Quick,
    LookUp(colCT_Quick, FieldKey = ThisItem.FieldKey),
    {
        ValueText: Self.Text
    }
);

Set(varCT_IsDirty, true);
